import { t, ui, locale } from './i18n.js';
const html = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = value => Number.isFinite(value) ? new Intl.NumberFormat(locale(), {maximumFractionDigits: 1}).format(value) : t('Non disponibile');

export function resultInsightsHTML(insights, {scopeId = null, view = 'projects', failed = false} = {}) {
  const ready = insights && insights.scopeId === scopeId;
  const groups = ready ? insights[view] ?? [] : [];
  const card = item => {
    const {deliveries, calls, feedback} = item;
    return ui`<article class="result-insight-card"><div class="result-insight-title"><h4>${html(item.title)}</h4><span>${number(item.assignments)} ${view === 'procedures' ? t('incarichi') : t('incarichi e patch')}</span></div>${item.available === false ? ui`<p class="governance-caption">Nome non disponibile in questo ambito; conteggi storici conservati.</p>` : ''}<dl class="result-insight-facts"><div><dt>Consegne valutate</dt><dd>${number(deliveries.approved)} ${t('approvate')} · ${number(deliveries.revised)} ${t('da rivedere')}<small>${number(deliveries.pending)} ${t('in attesa di decisione')}</small></dd></div><div><dt>Chiamate AI registrate</dt><dd>${number(calls.total)}<small>${number(calls.succeeded)} ${t('riuscite')} · ${number(calls.running)} ${t('in corso')}</small></dd></div><div><dt>Utilità dichiarata</dt><dd>${feedback.responses ? ui`${number(feedback.helpful)} utili su ${number(feedback.responses)} valutazioni` : t('Non ancora valutata')}<small>${number(feedback.missing)} ${t('risultati approvati da valutare')}</small></dd></div><div><dt>Minuti risparmiati dichiarati</dt><dd>${number(feedback.minutesSaved)}<small>${number(feedback.minutesSavedEntries)} ${t('stime inserite da te')}</small></dd></div></dl><details class="result-insight-details"><summary>Leggi come contiamo questi risultati</summary><p>${t('Approvazioni e revisioni contano le singole versioni delle consegne. L’utilità conta una valutazione aggiornata per incarico o patch approvata; le valutazioni mancanti non sono giudizi negativi.')}</p><p>${t('Chiamate fallite')}: ${number(calls.failed)} · ${t('Annullate')}: ${number(calls.cancelled)} · ${t('Tempo scaduto')}: ${number(calls.timedOut)} · ${t('Interrotte')}: ${number(calls.interrupted)}.</p></details></article>`;
  };
  return ui`<section class="governance-section result-insights"><div class="governance-title-row"><h3>Dove il lavoro è utile</h3><span class="ops-scope-tag">${scopeId ? t('Ambito attuale') : t('Tutti gli ambiti')}</span></div><p class="governance-caption">Lo storico conservato mette a confronto le decisioni sulle consegne, i tentativi AI e le tue valutazioni. Nessuna stima automatica di risparmio o costo.</p><div class="result-insight-switch" role="group" aria-label="Raggruppa i risultati"><button type="button" class="ops-button${view === 'projects' ? ' is-primary' : ''}" data-governance-action="insight-view" data-view="projects" aria-pressed="${view === 'projects'}">Per progetto</button><button type="button" class="ops-button${view === 'procedures' ? ' is-primary' : ''}" data-governance-action="insight-view" data-view="procedures" aria-pressed="${view === 'procedures'}">Per procedura</button></div>${!ready ? ui`<p class="governance-empty" role="status">${failed ? t('Risultati dell’ambito non disponibili. Usa Aggiorna dati per riprovare.') : t('Caricamento dei risultati dell’ambito…')}</p>` : groups.length ? ui`<div class="result-insight-list">${groups.map(card).join('')}</div>` : ui`<p class="governance-empty">${view === 'projects' ? t('Crea un incarico in un progetto: qui vedrai le consegne e potrai confrontarle con il lavoro richiesto.') : t('Usa una procedura per un incarico: qui vedrai le consegne, le chiamate registrate e le valutazioni ricevute.')}</p>`}${ready ? ui`<p class="governance-caption">${view === 'projects' ? ui`${number(insights.coverage.callsWithoutProject)} chiamate senza progetto, escluse da questo confronto.` : ui`${number(insights.coverage.callsWithoutProcedure)} chiamate senza una procedura attribuibile, escluse da questo confronto.`} ${t('Le chiamate includono i tentativi falliti, annullati e interrotti. I minuti sono stime personali facoltative.')}</p>` : ''}</section>`;
}
